cmd:
cd /app && cat > hk/nginx-site <<'EOF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    root /var/www/gitrepo;
    index index.html;
    server_name _;
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
cp hk/nginx-site /etc/nginx/sites-available/gitrepo && ln -sf /etc/nginx/sites-available/gitrepo /etc/nginx/sites-enabled/gitrepo && rm -f /etc/nginx/sites-enabled/default && nginx -t 2>&1
